const cache = new Map<string, Glyphs>();

/** the glyphs of a font by the name it was loaded by */
export function glyphsFor(name: string): Glyphs {
  const key = name.toLowerCase() in FONT_DATA ? name.toLowerCase() : 'fixed';
  let g = cache.get(key);
  if (!g) {
    g = glyphsOf(FONT_DATA[key]);
    cache.set(key, g);
  }
  return g;
}
